begin;
select set_config('request.jwt.claim.sub',(select id::text from auth.users order by created_at limit 1),true) is not null as identity_ready;
-- Fixtures run inside a rollback transaction; role ACLs are checked separately.
do $$
declare did uuid;other_driver uuid;vid uuid;pid uuid=gen_random_uuid();req uuid=gen_random_uuid();nid uuid=gen_random_uuid();fid uuid=gen_random_uuid();unassigned uuid=gen_random_uuid();report uuid=gen_random_uuid();photo uuid=gen_random_uuid();token text;result jsonb;expected timestamptz;old_sub text;started timestamptz;
begin
 insert into rl_crm_drivers(full_name) values('DRIVER-SERVICE-ROLLBACK') returning id into did;
 insert into rl_crm_drivers(full_name) values('DRIVER-OTHER-ROLLBACK') returning id into other_driver;
 insert into rl_crm_vehicles(plate,assigned_driver_id,odometer_km,next_service_km,service_interval_km) values('SERVICE-ROLLBACK',did,100,1000,1000) returning id into vid;
 perform respectlogistic_driver_access(did,'password','rollback-'||did::text,'TemporaryPassword-123');
 result=respectlogistic_driver_login('rollback-'||did::text,'TemporaryPassword-123');token=result->>'token';
 if token is null or not (result->>'must_change_password')::boolean then raise exception 'TEST: login / first password';end if;
 begin perform respectlogistic_driver_service(token);raise exception using message='TEST: temporary password accessed data',errcode='P0002';exception when sqlstate '28000' then null;end;
 perform respectlogistic_driver_password(token,'PermanentPassword-456');
 perform respectlogistic_driver_service(token);
 perform respectlogistic_save_service_partner(jsonb_build_object('id',pid,'name','ROLLBACK SERVICE','address','Test road 1','phone','+70000000000','working_hours','09:00-18:00','time_zone','Europe/Moscow','contract_number','TEST','contract_from',current_date,'work_kinds',jsonb_build_array('service','oil')));
 perform respectlogistic_create_service_request(jsonb_build_object('id',req,'vehicle_id',vid,'partner_id',pid,'kind','service','reported_odometer',110,'requested_date',current_date+1),token);
 select modified_at into expected from respectlogistic_service_requests where id=req;
 begin perform respectlogistic_service_action(req,'confirm',expected,jsonb_build_object('service_agreed',true,'scheduled_local',((now()+interval '1 day') at time zone 'Europe/Moscow')::text),token);raise exception using message='TEST: driver confirmed booking',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_service_action(req,'confirm',expected,jsonb_build_object('service_agreed',true,'scheduled_local',((now()+interval '1 day') at time zone 'Europe/Moscow')::text));
 begin perform respectlogistic_service_action(req,'arrived',expected,'{}',token);raise exception using message='TEST: stale request accepted',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 select modified_at into expected from respectlogistic_service_requests where id=req;
 perform respectlogistic_service_action(req,'arrived',expected,'{}',token);
 select modified_at into expected from respectlogistic_service_requests where id=req;
 perform respectlogistic_service_action(req,'complete',expected,jsonb_build_object('performed_date',current_date,'odometer',120));
 if not exists(select 1 from rl_crm_vehicles where id=vid and odometer_km=120 and next_service_km=1120) then raise exception 'TEST: maintenance not updated';end if;
 perform respectlogistic_save_driver_note(jsonb_build_object('id',nid,'driver_id',did,'title','Test access','login','TESTLOGIN','password','TESTSECRET','body','Paper required'));
 result=respectlogistic_read_driver_note(nid,token);
 if result->>'password'<>'TESTSECRET' then raise exception 'TEST: note decryption';end if;
 perform respectlogistic_duty_action(token,vid,'start',120);
 select started_at into started from respectlogistic_driver_duties where driver_id=did and ended_at is null;
 begin perform respectlogistic_duty_action(token,vid,'start',120);raise exception using message='TEST: duplicate duty',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_save_road_fine(jsonb_build_object('id',fid,'vehicle_id',vid,'violation_at',clock_timestamp(),'amount',500,'notice_number','ROLLBACK-'||fid::text,'location','Test road','reason','Speeding'));
 if not exists(select 1 from respectlogistic_road_fines where id=fid and driver_id=did and assignment='duty') then raise exception 'TEST: duty attribution';end if;
 perform respectlogistic_save_road_fine(jsonb_build_object('id',unassigned,'vehicle_id',vid,'violation_at',started-interval '1 hour','amount',500,'notice_number','ROLLBACK-'||unassigned::text,'location','Test road','reason','Speeding'));
 if not exists(select 1 from respectlogistic_road_fines where id=unassigned and driver_id is null) then raise exception 'TEST: current assignment used for historical fine';end if;
 perform respectlogistic_road_fine_response(token,fid,'I was not speeding');
 if respectlogistic_prepare_road_fine(fid) is distinct from respectlogistic_prepare_road_fine(fid) then raise exception 'TEST: duplicate payroll fine';end if;
 if exists(select 1 from crm_payroll_deductions where fine_id=(select linked_fine_id from respectlogistic_road_fines where id=fid)) then raise exception 'TEST: notice automatically deducted salary';end if;
 perform respectlogistic_create_shift_report(token,jsonb_build_object('id',report,'vehicle_id',vid,'shift_date',current_date,'odometer',150,'technical_note','Check brakes','supplies_note','Printer tape'));
 select modified_at into expected from respectlogistic_driver_shift_reports where id=report;
 begin perform respectlogistic_shift_action(report,'submit',expected,'{}',token);raise exception using message='TEST: shift without odometer photo',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_upload_photo(token,jsonb_build_object('id',photo,'report_id',report,'kind','odometer','file_name','test.jpg'),'/9j/2Q==');
 perform respectlogistic_shift_action(report,'submit',expected,'{}',token);
 if exists(select 1 from respectlogistic_driver_duties where driver_id=did and ended_at is null) then raise exception 'TEST: submitted report did not end duty';end if;
 select modified_at into expected from respectlogistic_driver_shift_reports where id=report;
 perform respectlogistic_shift_action(report,'review',expected);
 if not exists(select 1 from rl_crm_vehicles where id=vid and odometer_km=150) then raise exception 'TEST: shift mileage';end if;
 old_sub=current_setting('request.jwt.claim.sub');perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform respectlogistic_read_driver_note(nid);raise exception using message='TEST: other owner note',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform set_config('request.jwt.claim.sub',old_sub,true);
 perform respectlogistic_driver_access(other_driver,'password','rollback-'||other_driver::text,'TemporaryPassword-123');
 result=respectlogistic_driver_login('rollback-'||other_driver::text,'TemporaryPassword-123');
 perform respectlogistic_driver_password(result->>'token','PermanentPassword-456');
 begin perform respectlogistic_read_driver_note(nid,result->>'token');raise exception using message='TEST: other driver note',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 begin perform respectlogistic_road_fine_response(result->>'token',fid,'Foreign response');raise exception using message='TEST: other driver fine',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_access(did,'block');
 begin perform respectlogistic_driver_service(token);raise exception using message='TEST: blocked session active',errcode='P0002';exception when sqlstate '28000' then null;end;
end$$;
rollback;
select 'PASS: access/password/revocation, driver/owner isolation, booking workflow/stale writes, maintenance schedule, encrypted note reveal, duty timestamps and historical fine attribution, objections, odometer photo requirement and report review. Fixtures rolled back.' as verification;
